def go(n,h,v=None):
    if v is None:
        v = {}
    if (n,h) not in v:
        if n == 0:
            v[(n,h)] = 1
        else:
            if h != 0:
                sum_value = 0
                for i in range(n):
                    sum_value += go(i,h-1,v) * go(n-1-i,h-1,v)
                v[(n,h)] = sum_value
            else:
                v[(n,h)] = 0
    return v[(n,h)]

import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    static Map<String, Integer> v = new HashMap<>();

    public static int go(int n, int h) {
        String key = n + "," + h;
        if (!v.containsKey(key)) {
            if (n == 0) {
                v.put(key, 1);
            } else {
                if (h != 0) {
                    int sum_value = 0;
                    for (int i = 0; i < n; i++) {
                        sum_value += go(i, h - 1) * go(n - 1 - i, h - 1);
                    }
                    v.put(key, sum_value);
                } else {
                    v.put(key, 0);
                }
            }
        }
        return v.get(key);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int h = scanner.nextInt();
        int result = go(n, n) - go(n, Math.max(0, h - 1));
        System.out.println(result);
    }
}

